#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

// Structure to define the value returned by the thread
typedef struct {
    int code;
    char msg[64];
} thread_result_t;

void *worker_function(void *arg) {
    // Allocate memory for the return value on the heap, as the stack goes away upon exit
    thread_result_t *result = malloc(sizeof(thread_result_t));
    if (result == NULL) {
        perror("malloc");
        return NULL;
    }

    result->code = 200;
    strcpy(result->msg, "Calculation complete.");

    // Exit and return the pointer to the structure
    pthread_exit((void *)result);
}

int main() {
    pthread_t thread_id;
    void *exit_status = NULL;
    int s;

    // 1. Create a joinable thread
    s = pthread_create(&thread_id, NULL, worker_function, NULL);
    if (s != 0) {
        fprintf(stderr, "Error creating thread: %s\n", strerror(s));
        return 1;
    }

    printf("Main thread waiting for worker...\n");

    // 2. Wait for the thread to terminate and retrieve its status
    s = pthread_join(thread_id, &exit_status);

    if (s != 0) {
        fprintf(stderr, "Error joining thread: %s\n", strerror(s));
        return 1;
    }

    // 3. Process and free the retrieved data
    thread_result_t *result_data = (thread_result_t *)exit_status;

    if (result_data != NULL) {
        printf("Worker thread terminated. Exit Code: %d, Message: %s\n", 
               result_data->code, result_data->msg);
        free(result_data); // Free memory allocated by the worker
    } else {
        printf("Worker thread terminated with NULL status.\n");
    }

    return 0;
}
